function endTour(){tourIndex=-1;$('tour').hidden=true;document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));}
function showTour(){document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));const step=tourSteps[tourIndex];if(!step){endTour();toast('Try a new intention or import your own attendee list.');return;}step.action();$('tour').hidden=false;$('tourStep').textContent=`DEMO WALKTHROUGH / ${tourIndex+1} OF ${tourSteps.length}`;$('tourTitle').textContent=step.title;$('tourText').textContent=step.text;$('tourDots').innerHTML=tourSteps.map((s,i)=>`<i class="${i===tourIndex?'active':''}"></i>`).join('');$('tourNext').innerHTML=(tourIndex===tourSteps.length-1?'Explore on your own':'Next')+icon('arrow');const target=$(step.target);target?.classList.add('tour-highlight');target?.scrollIntoView({behavior:'smooth',block:'center'});}
icons();
for(const id of ['profileButton','editProfile'])$(id).onclick=openProfile;
for(const id of ['methodButton','methodFooter'])$(id).onclick=()=>$('infoDialog').showModal();
// Profile panel remains easy to edit on small screens where its tiny label is hidden.
document.querySelector('.profile-summary').onclick=openProfile;
$('closeInfo').onclick=()=>$('infoDialog').close();
$('profileForm').onsubmit=e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();if(!$('editName').value.trim()){toast('Add your name.');return;}profile={name:$('editName').value.trim(),title:$('editTitle').value.trim(),background:$('editBackground').value.trim(),interests:$('editInterests').value.trim()};$('profileDialog').close();selected='';compute();toast('Profile updated. Your shortlist has been recalculated.');};
 $('goal').oninput=()=>{$('changeHint').textContent='Click “Find my people” to update.';$('changeHint').classList.add('pending');};
$('rankButton').onclick=()=>{const next=$('goal').value.trim();if(!next){toast('Describe what you want from this event.');return;}goal=next;selected='';all=false;compute();toast('Shortlist updated for your intention.');};
$('listTab').onclick=()=>setView('list');$('mapTab').onclick=()=>setView('map');$('showAll').onclick=()=>{all=!all;renderResults();};
$('search').oninput=e=>{query=e.target.value;renderResults();};$('discoverNav').onclick=()=>setNav(false);$('savedNav').onclick=()=>setNav(true);
$('importButton').onclick=()=>$('attendeeFile').click();$('attendeeFile').onchange=e=>importFile(e.target.files[0]);$('useWorkbook').onclick=loadWorkbook;
$('resetButton').onclick=()=>{importRevision++;endTour();reset();toast('Sample event reset.');};$('exportButton').onclick=exportPlan;
$('resumeButton').onclick=()=>$('resumeFile').click();$('resumeFile').onchange=e=>readResume(e.target.files[0]);
$('tourButton').onclick=()=>{importRevision++;reset();tourIndex=0;showTour();};$('tourNext').onclick=()=>{tourIndex++;showTour();};$('closeTour').onclick=endTour;
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
compute();
